struct Node {
    int val;
    Node *left;
    Node *right;
    Node *next;
    Node(int v) : val(v), left(nullptr), right(nullptr), next(nullptr) {}
};

class Solution {
public:
    Node* connect(Node* root) {
        if (!root) return nullptr;
        Node *cur = root;
        while (cur->left) {
            Node *head = cur;
            while (head) {
                head->left->next = head->right;
                if (head->next) head->right->next = head->next->left;
                head = head->next;
            }
            cur = cur->left;
        }
        return root;
    }
};

