#include <bits/stdc++.h>
using namespace std;

struct Node {
    int val;
    Node *left;
    Node *right;
    Node *next;
    Node(int v) : val(v), left(nullptr), right(nullptr), next(nullptr) {}
};
vector<string> tok(const string &s) {
    string t = s;
    for (char &c : t)
        if (c == ',' || c == '[' || c == ']') c = ' ';
    vector<string> v;
    string w;
    stringstream ss(t);
    while (ss >> w) v.push_back(w);
    return v;
}

string readAll() {
    string s, ln;
    while (getline(cin, ln)) s += ln + "\n";
    return s;
}

vector<string> readLines() {
    vector<string> lines;
    string ln;
    while (getline(cin, ln))
        if (ln.find_first_not_of(" \t\r") != string::npos) lines.push_back(ln);
    return lines;
}
Node *buildNode(const vector<string> &v) {
    if (v.empty() || v[0] == "null") return nullptr;
    Node *root = new Node(stoi(v[0]));
    queue<Node *> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < v.size()) {
        Node *cur = q.front();
        q.pop();
        if (i < v.size()) {
            if (v[i] != "null") {
                cur->left = new Node(stoi(v[i]));
                q.push(cur->left);
            }
            i++;
        }
        if (i < v.size()) {
            if (v[i] != "null") {
                cur->right = new Node(stoi(v[i]));
                q.push(cur->right);
            }
            i++;
        }
    }
    return root;
}
int main() {
    Node *root = buildNode(tok(readAll()));
    Node *cur = root;
    while (cur && cur->left) {
        Node *head = cur;
        while (head) {
            head->left->next = head->right;
            if (head->next) head->right->next = head->next->left;
            head = head->next;
        }
        cur = cur->left;
    }
    vector<string> out;
    vector<Node *> q;
    if (root) q.push_back(root);
    while (!q.empty()) {
        vector<Node *> nxt;
        for (Node *n : q) {
            out.push_back(to_string(n->val));
            if (n->left) nxt.push_back(n->left);
            if (n->right) nxt.push_back(n->right);
        }
        out.push_back("#");
        q = nxt;
    }
    if (out.empty()) {
        cout << "[]" << endl;
        return 0;
    }
    string s = "[";
    for (size_t i = 0; i < out.size(); i++) {
        if (i) s += ",";
        s += out[i];
    }
    cout << s + "]" << endl;
    return 0;
}

