class Solution {
public:
    bool rows[9][9] = {}, cols[9][9] = {}, boxes[9][9] = {};
    void solveSudoku(vector<vector<char>>& board) {
        for (int i = 0; i < 9; i++)
            for (int j = 0; j < 9; j++)
                if (board[i][j] != '.') mark(i, j, board[i][j] - '1', true);
        dfs(board, 0);
    }
    void mark(int i, int j, int d, bool v) {
        rows[i][d] = v;
        cols[j][d] = v;
        boxes[i / 3 * 3 + j / 3][d] = v;
    }
    bool dfs(vector<vector<char>>& board, int pos) {
        for (int p = pos; p < 81; p++) {
            int i = p / 9, j = p % 9;
            if (board[i][j] != '.') continue;
            for (int d = 0; d < 9; d++) {
                if (rows[i][d] || cols[j][d] || boxes[i / 3 * 3 + j / 3][d]) continue;
                board[i][j] = (char)('1' + d);
                mark(i, j, d, true);
                if (dfs(board, p + 1)) return true;
                board[i][j] = '.';
                mark(i, j, d, false);
            }
            return false;
        }
        return true;
    }
};

