class Solution {
public:
    int n;
    vector<bool> cols, d1, d2;
    int totalNQueens(int n_) {
        n = n_;
        cols.assign(n, false);
        d1.assign(2 * n, false);
        d2.assign(2 * n, false);
        return dfs(0);
    }
    int dfs(int r) {
        if (r == n) return 1;
        int cnt = 0;
        for (int c = 0; c < n; c++) {
            int a = r - c + n - 1, b = r + c;
            if (cols[c] || d1[a] || d2[b]) continue;
            cols[c] = d1[a] = d2[b] = true;
            cnt += dfs(r + 1);
            cols[c] = d1[a] = d2[b] = false;
        }
        return cnt;
    }
};

