#include <bits/stdc++.h>
using namespace std;

vector<string> tok(const string &s) {
    string t = s;
    for (char &c : t)
        if (c == ',' || c == '[' || c == ']') c = ' ';
    vector<string> v;
    string w;
    stringstream ss(t);
    while (ss >> w) v.push_back(w);
    return v;
}

string readAll() {
    string s, ln;
    while (getline(cin, ln)) s += ln + "\n";
    return s;
}

vector<string> readLines() {
    vector<string> lines;
    string ln;
    while (getline(cin, ln))
        if (ln.find_first_not_of(" \t\r") != string::npos) lines.push_back(ln);
    return lines;
}
vector<vector<int>> res;
vector<int> path;
int K;

void dfs(int n, int start) {
    if ((int)path.size() == K) {
        res.push_back(path);
        return;
    }
    for (int i = start; i <= n - (K - (int)path.size()) + 1; i++) {
        path.push_back(i);
        dfs(n, i + 1);
        path.pop_back();
    }
}

int main() {
    vector<string> t = tok(readAll());
    int n = stoi(t[0]);
    K = stoi(t[1]);
    dfs(n, 1);
    for (size_t i = 0; i < res.size(); i++) {
        for (size_t j = 0; j < res[i].size(); j++) {
            if (j) cout << " ";
            cout << res[i][j];
        }
        cout << "\n";
    }
    return 0;
}
